def normalize(data: list, config: dict) -> dict:
    extract = config.get('extract', {})
    result = {}

    entity_maps = {}
    for entity_name, fields in extract.items():
        entity_maps[entity_name] = {}
        result[entity_name] = []

    items = []

    for row in data:
        item = dict(row)

        for entity_name, fields in extract.items():
            values = tuple(row.get(f) for f in fields)

            if values not in entity_maps[entity_name]:
                entity_id = len(entity_maps[entity_name]) + 1
                entity_maps[entity_name][values] = entity_id
                entity_record = {'id': entity_id}
                for f in fields:
                    entity_record[f] = row.get(f)
                result[entity_name].append(entity_record)

            fk_name = entity_name.rstrip('s') + 'Id'
            if entity_name.endswith('ies'):
                fk_name = entity_name[:-3] + 'yId'
            elif entity_name.endswith('ses'):
                fk_name = entity_name[:-2] + 'Id'
            elif entity_name.endswith('s'):
                fk_name = entity_name[:-1] + 'Id'

            item[fk_name] = entity_maps[entity_name][values]
            for f in fields:
                item.pop(f, None)

        items.append(item)

    result['items'] = items
    return result

solution.javascript:
function normalize(data, config) {
  const extract = config.extract || {};
  const result = {};
  const entityMaps = {};

  for (const entityName of Object.keys(extract)) {
    entityMaps[entityName] = new Map();
    result[entityName] = [];
  }

  const items = [];

  for (const row of data) {
    const item = { ...row };

    for (const [entityName, fields] of Object.entries(extract)) {
      const key = fields.map(f => row[f]).join('||');

      if (!entityMaps[entityName].has(key)) {
        const id = entityMaps[entityName].size + 1;
        entityMaps[entityName].set(key, id);
        const record = { id };
        for (const f of fields) record[f] = row[f];
        result[entityName].push(record);
      }

      let fkName;
      if (entityName.endsWith('ies')) fkName = entityName.slice(0, -3) + 'yId';
      else if (entityName.endsWith('s')) fkName = entityName.slice(0, -1) + 'Id';
      else fkName = entityName + 'Id';

      item[fkName] = entityMaps[entityName].get(key);
      for (const f of fields) delete item[f];
    }

    items.push(item);
  }

  result.items = items;
  return result;
}
